"""Frozen archives produced by historical code, never regenerated by the tests."""
import gzip
import hashlib
import json
from pathlib import Path
import pytest
from app.config import get_settings
from app.services import ai_service, resume_compiler

ROOT = Path(__file__).parent / "fixtures" / "compatibility"
CASES = json.loads((ROOT / "manifest.json").read_text(encoding="utf-8"))


@pytest.fixture
def migrated_client(client, tmp_path):
    from sqlalchemy.orm import Session
    from app.database import build_engine, get_db
    from app.main import app
    from app.migrations import run_migrations
    url = "sqlite:///" + (tmp_path / "historical-restore.db").as_posix()
    run_migrations(url)
    engine = build_engine(url)
    previous = app.dependency_overrides[get_db]
    def sessions():
        with Session(engine) as session:
            yield session
    app.dependency_overrides[get_db] = sessions
    try:
        yield client
    finally:
        app.dependency_overrides[get_db] = previous
        engine.dispose()


@pytest.mark.parametrize("case", CASES, ids=lambda c: f"backup-v{c['version']}")
def test_real_historical_archive_restore_and_reexport(migrated_client, monkeypatch, tmp_path, case):
    client = migrated_client
    monkeypatch.setattr(get_settings(), "asset_storage_dir", str(tmp_path))
    monkeypatch.setattr(ai_service, "get_tailoring_output", lambda *a, **k: pytest.fail("Restore called a model"))
    monkeypatch.setattr(resume_compiler, "compile_pdf", lambda *a: pytest.fail("Historical export recompiled"))
    raw = gzip.decompress((ROOT / case["file"]).read_bytes())
    assert hashlib.sha256(raw).hexdigest() == case["sha256"]
    original = json.loads(raw)
    for cycle in range(2):
        preview = client.post("/api/data/restore-preview", files={"file": ("historical.json", raw)})
        assert preview.status_code == 200, preview.text
        restored = client.post("/api/data/restore", files={"file": ("historical.json", raw)}, data={"sha256": preview.json()["sha256"], "confirmation": "RESTORE"})
        assert restored.status_code == 200, restored.text
        assert client.get(f"/api/jobs/{case['job']}").status_code == 200
        if "baseline" in case:
            url = f"/api/tailoring/resumes/{case['baseline']}"
            view = client.get(url)
            assert view.status_code == 200, view.text
            assert view.json()["revision"]["validation"]["valid"]
            assert bool(view.json()["approval"]) == (case["version"] >= 5)
            renders = client.get(url + f"/renders?revision_id={case['baseline']}").json()
            assert bool(renders) == (case["version"] >= 6)
        for route, sha in case["downloads"].items():
            download = client.get(route)
            assert download.status_code == 200, download.text
            assert hashlib.sha256(download.content).hexdigest() == sha
        current = client.get("/api/data/backup")
        assert current.status_code == 200
        for table, rows in original["tables"].items():
            assert current.json()["tables"][table] == rows
        raw = current.content


def test_future_archive_rejection_preserves_current_data(client, monkeypatch, tmp_path):
    monkeypatch.setattr(get_settings(), "asset_storage_dir", str(tmp_path))
    job = client.post("/api/jobs", json={"company": "Keep me", "role_title": "Engineer"}).json()
    raw = json.loads(gzip.decompress((ROOT / CASES[-1]["file"]).read_bytes()))
    raw["version"] = 999
    payload = json.dumps(raw).encode()
    for route in ("/api/data/restore-preview", "/api/data/restore"):
        response = client.post(route, files={"file": ("future.json", payload)}, data={"sha256": hashlib.sha256(payload).hexdigest(), "confirmation": "RESTORE"})
        assert response.status_code == 400
    assert client.get(f"/api/jobs/{job['id']}").json() == job
